type Constructor<T = {}> = new (...args: any[]) => T;

// family-wide behaviour is composed as METHODS; there is no operator variant
function Comparable<TBase extends Constructor<{ key(): number }>>(Base: TBase) {
  return class extends Base {
    lessThan(other: InstanceType<TBase>) { return this.key() < other.key(); }
  };
}
class Version extends Comparable(class { constructor(readonly n = 0) { super(); } key() { return this.n; } }) {}
new Version(1).lessThan(new Version(2));   // a method call: TS has no '<' for classes
